export function hasMatchingBrackets(text) {
  const stack = [];
  const openingFor = { ')': '(', ']': '[', '}': '{' };
  for (const char of text) {
    if (char === '(' || char === '[' || char === '{') stack.push(char);
    else if (stack.pop() !== openingFor[char]) return false;
  }
  return stack.length === 0;
}
